## Python Sidecar Engine (FastAPI)

```python
# sidecar_engine.py
import asyncio
import signal
import sys
import threading
import time
import queue
import psutil
import GPUtil
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from typing import Dict, List, Optional
import logging

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

app = FastAPI(title="Sidecar Engine", version="1.0.0")

class HealthResponse(BaseModel):
    timestamp: str
    cpu_percent: float
    memory_usage: Dict[str, float]
    vram_usage: Optional[List[Dict[str, float]]]
    uptime: float
    is_healthy: bool

class TaskRequest(BaseModel):
    task_type: str
    data: Dict = {}
    priority: int = 0

# Global state
shutdown_event = threading.Event()
task_queue = queue.Queue()
worker_running = False

def get_system_health() -> HealthResponse:
    """Get current system health metrics"""
    try:
        # CPU usage
        cpu_percent = psutil.cpu_percent(interval=1)

        # Memory usage
        memory = psutil.virtual_memory()
        memory_usage = {
            "total_gb": round(memory.total / (1024**3), 2),
            "available_gb": round(memory.available / (1024**3), 2),
            "used_gb": round(memory.used / (1024**3), 2),
            "percent": memory.percent
        }

        # VRAM usage (if available)
        vram_usage = None
        try:
            gpus = GPUtil.getGPUs()
            if gpus:
                vram_usage = []
                for gpu in gpus:
                    vram_usage.append({
                        "gpu_id": gpu.id,
                        "name": gpu.name,
                        "memory_total_mb": gpu.memoryTotal,
                        "memory_used_mb": gpu.memoryUsed,
                        "memory_free_mb": gpu.memoryFree,
                        "memory_utilization_percent": round((gpu.memoryUsed / gpu.memoryTotal) * 100, 2)
                    })
        except Exception as e:
            logger.warning(f"Could not get VRAM info: {e}")

        return HealthResponse(
            timestamp=time.strftime("%Y-%m-%dT%H:%M:%SZ"),
            cpu_percent=cpu_percent,
            memory_usage=memory_usage,
            vram_usage=vram_usage,
            uptime=time.time(),
            is_healthy=True
        )
    except Exception as e:
        logger.error(f"Error getting system health: {e}")
        return HealthResponse(
            timestamp=time.strftime("%Y-%m-%dT%H:%M:%SZ"),
            cpu_percent=0.0,
            memory_usage={"total_gb": 0, "available_gb": 0, "used_gb": 0, "percent": 0},
            vram_usage=None,
            uptime=time.time(),
            is_healthy=False
        )

def background_worker():
    """Background worker that processes tasks from the queue"""
    global worker_running
    worker_running = True

    logger.info("Background worker started")

    while not shutdown_event.is_set():
        try:
            # Process tasks with timeout
            task = task_queue.get(timeout=1.0)
            if task is None:  # Poison pill
                break

            # Simulate task processing
            logger.info(f"Processing task: {task.task_type}")

            # Here you would implement actual task logic
            # For demo, we'll just sleep and log
            time.sleep(0.1)

            task_queue.task_done()

        except queue.Empty:
            continue
        except Exception as e:
            logger.error(f"Error in background worker: {e}")
            continue

    worker_running = False
    logger.info("Background worker stopped")

# API Endpoints
@app.get("/api/health", response_model=HealthResponse)
async def health_check():
    """Get current system health metrics"""
    return get_system_health()

@app.post("/api/task")
async def submit_task(task: TaskRequest):
    """Submit a task to the background worker"""
    try:
        task_queue.put(task)
        return {"status": "queued", "task_id": str(hash(str(task)))}
    except Exception as e:
        logger.error(f"Error submitting task: {e}")
        raise HTTPException(status_code=500, detail=str(e))

@app.get("/api/queue/stats")
async def queue_stats():
    """Get current queue statistics"""
    return {
        "queue_size": task_queue.qsize(),
        "is_running": worker_running
    }

# Graceful shutdown handling
def signal_handler(signum, frame):
    """Handle graceful shutdown signals"""
    logger.info(f"Received signal {signum}, shutting down gracefully...")
    shutdown_event.set()

    # Stop background worker
    try:
        task_queue.put(None)  # Poison pill to stop worker
    except:
        pass

    sys.exit(0)

# Register signal handlers
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Start background worker thread
worker_thread = threading.Thread(target=background_worker, daemon=True)
worker_thread.start()

if __name__ == "__main__":
    import uvicorn

    # For development testing
    logger.info("Starting sidecar engine...")
    uvicorn.run(
        "sidecar_engine:app",
        host="127.0.0.1",
        port=8000,
        log_level="info"
    )
```

## Node.js Client with Exponential Backoff

```javascript
// client.js
const { spawn } = require('child_process');
const axios = require('axios');
const { setTimeout: sleep } = require('timers/promises');

class SidecarManager {
    constructor() {
        this.process = null;
        this.healthUrl = 'http://127.0.0.1:8000/api/health';
        this.maxRetries = 10;
        this.baseDelay = 1000; // ms
        this.maxDelay = 30000; // ms
    }

    async startSidecar() {
        try {
            console.log('Starting sidecar engine...');

            // Spawn the Python process
            this.process = spawn('python3', ['sidecar_engine.py'], {
                stdio: 'pipe',
                cwd: __dirname
            });

            // Handle process output
            this.process.stdout.on('data', (data) => {
                console.log(`[SIDE CAR] ${data.toString()}`);
            });

            this.process.stderr.on('data', (data) => {
                console.error(`[SIDE CAR ERROR] ${data.toString()}`);
            });

            this.process.on('close', (code, signal) => {
                console.log(`Sidecar process exited with code ${code} and signal ${signal}`);
                if (this.process) {
                    this.process = null;
                }
            });

            this.process.on('error', (error) => {
                console.error('Failed to start sidecar:', error);
                throw new Error('Failed to start sidecar engine');
            });

            // Wait for health endpoint to be available
            await this.waitForHealthEndpoint();
            console.log('Sidecar engine is ready!');

        } catch (error) {
            console.error('Error starting sidecar:', error);
            throw error;
        }
    }

    async waitForHealthEndpoint() {
        let retryCount = 0;
        let delay = this.baseDelay;

        while (retryCount < this.maxRetries) {
            try {
                const response = await axios.get(this.healthUrl, {
                    timeout: 5000,
                    validateStatus: function (status) {
                        return status < 500; // Accept 2xx and 4xx status codes
                    }
                });

                if (response.status === 200) {
                    console.log('Sidecar health endpoint is available');
                    return true;
                }

            } catch (error) {
                console.log(`Health check failed (attempt ${retryCount + 1}/${this.maxRetries}):`, error.message);
            }

            retryCount++;

            if (retryCount < this.maxRetries) {
                console.log(`Waiting ${delay}ms before next attempt...`);
                await sleep(delay);
                delay = Math.min(delay * 2, this.maxDelay); // Exponential backoff
            }
        }

        throw new Error('Sidecar engine did not become available within timeout period');
    }

    async submitTask(taskData) {
        if (!this.process) {
            throw new Error('Sidecar not running');
        }

        try {
            const response = await axios.post('http://127.0.0.1:8000/api/task', taskData, {
                timeout: 10000
            });

            console.log('Task submitted:', response.data);
            return response.data;
        } catch (error) {
            console.error('Failed to submit task:', error.message);
            throw error;
        }
    }

    async getQueueStats() {
        if (!this.process) {
            throw new Error('Sidecar not running');
        }

        try {
            const response = await axios.get('http://127.0.0.1:8000/api/queue/stats', {
                timeout: 5000
            });

            return response.data;
        } catch (error) {
            console.error('Failed to get queue stats:', error.message);
            throw error;
        }
    }

    async shutdown() {
        console.log('Shutting down sidecar engine...');

        if (this.process && !this.process.killed) {
            // Try graceful shutdown
            try {
                await axios.get('http://127.0.0.1:8000/api/health', {
                    timeout: 1000,
                    validateStatus: function (status) {
                        return status < 500;
                    }
                });
            } catch (error) {
                // Even if health check fails, try to kill process
            }

            // Force kill the process
            this.process.kill('SIGTERM');

            // Wait a bit for graceful shutdown
            await sleep(2000);

            if (!this.process.killed) {
                console.log('Force killing sidecar process...');
                this.process.kill('SIGKILL');
            }
        }

        this.process = null;
        console.log('Sidecar engine shut down successfully');
    }

    isRunning() {
        return this.process !== null && !this.process.killed;
    }
}

// Usage example
async function main() {
    const manager = new SidecarManager();

    try {
        // Start the sidecar
        await manager.startSidecar();

        // Test task submission
        console.log('Submitting test tasks...');
        await manager.submitTask({
            task_type: 'test_task',
            data: { message: 'Hello from Node.js!' },
            priority: 1
        });

        // Get queue stats
        const stats = await manager.getQueueStats();
        console.log('Queue stats:', stats);

        // Simulate some work
        await sleep(5000);

        // Submit another task
        await manager.submitTask({
            task_type: 'another_task',
            data: { message: 'Another test task' },
            priority: 0
        });

        // Show final queue stats
        const finalStats = await manager.getQueueStats();
        console.log('Final queue stats:', finalStats);

        // Shutdown after some time
        setTimeout(async () => {
            await manager.shutdown();
            process.exit(0);
        }, 10000);

    } catch (error) {
        console.error('Main error:', error);
        if (manager.isRunning()) {
            await manager.shutdown();
        }
        process.exit(1);
    }
}

// Handle graceful shutdown
process.on('SIGINT', async () => {
    console.log('\nReceived SIGINT, shutting down...');
    try {
        const manager = new SidecarManager();
        // Note: In a real scenario, you'd need to track the manager instance
        // This is a simplified version - in practice, store reference to manager
        process.exit(0);
    } catch (error) {
        console.error('Error during shutdown:', error);
        process.exit(1);
    }
});

// Start the application
if (require.main === module) {
    main();
}

module.exports = SidecarManager;
